package com.paymentplatform.distribution_service.api;
import com.paymentplatform.distribution_service.domain.*;import jakarta.validation.Valid;import jakarta.validation.constraints.Pattern;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController public class CashController {
 private final CashWorkflow workflow;private final CashStore store;public CashController(CashWorkflow workflow,CashStore store){this.workflow=workflow;this.store=store;}
 private String operator(Jwt jwt){String actor=jwt.getSubject();if(!"operator".equals(jwt.getClaims().get("actor_type"))||actor==null||actor.isBlank()||actor.length()>128||!actor.equals(actor.strip())||actor.chars().anyMatch(Character::isISOControl))throw CashStore.error(HttpStatus.FORBIDDEN,"OPERATOR_REQUIRED");return actor;}
 @PostMapping("/internal/v1/cash-operations") ResponseEntity<?> request(@AuthenticationPrincipal Jwt jwt,@RequestHeader("Idempotency-Key") @Pattern(regexp="[A-Za-z0-9][A-Za-z0-9._:-]{0,127}") String key,@Valid @RequestBody CashWorkflow.Request body){return ResponseEntity.status(201).cacheControl(CacheControl.noStore()).body(workflow.request(jwt.getClaimAsString("integrator_id"),operator(jwt),key,body));}
 @PostMapping("/internal/v1/cash-operations/{id}/approval") ResponseEntity<?> approve(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID id){var row=workflow.approve(jwt.getClaimAsString("integrator_id"),operator(jwt),id);return ResponseEntity.status(Set.of("ACCOUNTED","DISBURSED").contains(row.state())?200:202).cacheControl(CacheControl.noStore()).body(row);}
 @GetMapping("/internal/v1/cash-operations/{id}") ResponseEntity<?> get(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID id){operator(jwt);return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(store.get(jwt.getClaimAsString("integrator_id"),id));}
 @PostMapping("/internal/v1/cash-operations/{id}/disbursement") ResponseEntity<?> disburse(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID id){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(store.disburse(jwt.getClaimAsString("integrator_id"),operator(jwt),id));}
}
